package com.spawnmarker;

import net.runelite.api.GameState;
import net.runelite.api.coords.WorldPoint;

import java.util.function.IntConsumer;

final class CurrentRegionMarkerClearAction
{
	private CurrentRegionMarkerClearAction()
	{
	}

	static boolean execute(GameState gameState, WorldPoint playerLocation, IntConsumer clearRegion, Runnable resetControl)
	{
		try
		{
			if (gameState != GameState.LOGGED_IN || playerLocation == null)
			{
				return false;
			}

			clearRegion.accept(playerLocation.getRegionID());
			return true;
		}
		finally
		{
			resetControl.run();
		}
	}
}

package com.spawnmarker;

import java.awt.Color;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.List;

final class MarkerEditorCodec
{
	private static final String HEADER = "# regionId,regionX,regionY,plane,colorARGB,label";
	private static final Color DEFAULT_MARKER_COLOR = new Color(255, 108, 0);

	private MarkerEditorCodec()
	{
	}

	static String serialize(Collection<TilePoint> points)
	{
		List<TilePoint> sortedPoints = new ArrayList<>(points);
		sortedPoints.sort(Comparator
			.comparingInt(TilePoint::getRegionId)
			.thenComparingInt(TilePoint::getRegionX)
			.thenComparingInt(TilePoint::getRegionY)
			.thenComparingInt(TilePoint::getZ)
			.thenComparing(point -> point.getLabel() == null ? "" : point.getLabel()));

		StringBuilder text = new StringBuilder(HEADER);
		for (TilePoint point : sortedPoints)
		{
			Color color = point.getColor();
			String label = point.getLabel() == null ? "" : point.getLabel()
				.replace('\r', ' ')
				.replace('\n', ' ');

			text.append('\n')
				.append(point.getRegionId()).append(',')
				.append(point.getRegionX()).append(',')
				.append(point.getRegionY()).append(',')
				.append(point.getZ()).append(',')
				.append(color == null ? DEFAULT_MARKER_COLOR.getRGB() : color.getRGB()).append(',')
				.append(label);
		}

		return text.toString();
	}

	static List<TilePoint> deserialize(String text)
	{
		List<TilePoint> points = new ArrayList<>();
		if (text == null || text.trim().isEmpty())
		{
			return points;
		}

		String[] lines = text.split("\\R");
		for (int i = 0; i < lines.length; i++)
		{
			String line = lines[i].trim();
			if (line.isEmpty() || line.startsWith("#"))
			{
				continue;
			}

			String[] fields = line.split(",", 6);
			if (fields.length != 6)
			{
				throw invalidLine(i + 1, "expected six comma-separated fields");
			}

			try
			{
				int regionId = Integer.parseInt(fields[0].trim());
				int regionX = Integer.parseInt(fields[1].trim());
				int regionY = Integer.parseInt(fields[2].trim());
				int plane = Integer.parseInt(fields[3].trim());
				String colorValue = fields[4].trim();
				if (colorValue.isEmpty())
				{
					throw invalidLine(i + 1, "colorARGB is required");
				}

				Color color = new Color(Integer.parseInt(colorValue), true);
				String label = fields[5].trim();

				if (regionId < 0 || regionId > 65535 || regionX < 0 || regionX > 63
					|| regionY < 0 || regionY > 63 || plane < 0 || plane > 3)
				{
					throw invalidLine(i + 1, "coordinates are outside valid bounds");
				}

				points.add(new TilePoint(regionId, regionX, regionY, plane, color, label.isEmpty() ? null : label));
			}
			catch (NumberFormatException e)
			{
				throw invalidLine(i + 1, "coordinates or color are not valid integers");
			}
		}

		return points;
	}

	private static IllegalArgumentException invalidLine(int lineNumber, String reason)
	{
		return new IllegalArgumentException("Invalid saved marker data on line " + lineNumber + ": " + reason);
	}
}

package com.spawnmarker;

import java.util.Arrays;
import java.util.Collections;
import java.util.Locale;
import java.util.Set;
import java.util.stream.Collectors;

final class NpcNameFilter
{
	private enum Mode
	{
		DISABLED,
		DENY_LIST,
		ALLOW_LIST
	}

	private final Set<String> names;
	private final Mode mode;

	private NpcNameFilter(Set<String> names, Mode mode)
	{
		this.names = names;
		this.mode = mode;
	}

	static NpcNameFilter from(String configuredNames)
	{
		return denyList(configuredNames);
	}

	static NpcNameFilter disabled()
	{
		return new NpcNameFilter(Collections.emptySet(), Mode.DISABLED);
	}

	static NpcNameFilter denyList(String configuredNames)
	{
		return new NpcNameFilter(parseNames(configuredNames), Mode.DENY_LIST);
	}

	static NpcNameFilter allowList(String configuredNames)
	{
		return new NpcNameFilter(parseNames(configuredNames), Mode.ALLOW_LIST);
	}

	private static Set<String> parseNames(String configuredNames)
	{
		if (configuredNames == null || configuredNames.trim().isEmpty())
		{
			return Collections.emptySet();
		}

		return Arrays.stream(configuredNames.split("[,\\r\\n]+"))
			.map(String::trim)
			.filter(name -> !name.isEmpty())
			.map(NpcNameFilter::normalize)
			.collect(Collectors.toUnmodifiableSet());
	}

	boolean hides(String npcName)
	{
		if (npcName == null || mode == Mode.DISABLED)
		{
			return false;
		}

		boolean listed = names.contains(normalize(npcName));
		return mode == Mode.ALLOW_LIST ? !listed : listed;
	}

	boolean contains(String npcName)
	{
		return npcName != null && names.contains(normalize(npcName));
	}

	private static String normalize(String name)
	{
		return name.trim().toLowerCase(Locale.ROOT);
	}
}

package com.spawnmarker;

public enum NpcNameFilterMode
{
	OFF,
	DENY_LIST,
	ALLOW_LIST
}

package com.spawnmarker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(SpawnMarkerPlugin.CONFIG_GROUP)
public interface SpawnMarkerConfig extends Config
{
	String ADVANCED_SECTION = "advanced";
	String NON_COMBAT_SECTION = "nonCombatExceptions";

	@ConfigSection(
		name = "Combat level exceptions",
		description = "Allow listed NPCs to bypass the combat level filter.",
		position = 5
	)
	String nonCombatSection = NON_COMBAT_SECTION;

	@ConfigSection(
		name = "Advanced",
		description = "Edits are saved when focus leaves Saved markers. If malformed text is retained, right-click the Saved markers label and choose Reset to rebuild the editor from saved region data. This does not delete markers; reopen settings if the field remains blank.",
		position = 6,
		closedByDefault = true
	)
	String advancedSection = ADVANCED_SECTION;

	@ConfigItem(
		keyName = "filterMode",
		name = "NPC name filter mode",
		description = "Choose whether to ignore names, hide listed names, or show only listed names.",
		position = 0
	)
	default NpcNameFilterMode filterMode()
	{
		return NpcNameFilterMode.OFF;
	}

	@ConfigItem(
		keyName = "hiddenNpcNames",
		name = "Deny list NPC names",
		description = "NPC names whose markers are hidden in Deny list mode. Enter one name per line or separate names with commas.",
		position = 1
	)
	default String hiddenNpcNames()
	{
		return "";
	}

	@ConfigItem(
		keyName = "allowedNpcNames",
		name = "Allow list NPC names",
		description = "NPC names whose markers remain visible in Allow list mode. Enter one name per line or separate names with commas.",
		position = 2
	)
	default String allowedNpcNames()
	{
		return "";
	}

	@ConfigItem(
		keyName = "clearMarkers",
		name = "Clear all saved markers",
		description = "Select to permanently delete all saved spawn markers. This control resets after it runs.",
		position = 3
	)
	default boolean clearMarkers()
	{
		return false;
	}

	@ConfigItem(
		keyName = "clearCurrentRegionMarkers",
		name = "Clear markers in current region",
		description = "Delete saved markers for the region you are currently standing in, including its recovery copy. This control resets after it runs; you must be logged in.",
		position = 4
	)
	default boolean clearCurrentRegionMarkers()
	{
		return false;
	}

	@ConfigItem(
		keyName = "nonCombatNpcNames",
		name = "Allowed NPC names",
		description = "These NPC names can create markers even when their combat level is 0 or lower. Enter one name per line or separate names with commas.",
		position = 0,
		section = NON_COMBAT_SECTION
	)
	default String nonCombatNpcNames()
	{
		return "";
	}

	@ConfigItem(
		keyName = "markerData",
		name = "Saved markers",
		description = "One marker per line: regionId,regionX,regionY,plane,colorARGB,label. Delete a line to remove that marker; edits apply when you leave this field. To recover from malformed text, right-click this label and choose Reset. The editor is rebuilt from saved region data; reopen settings if it remains blank.",
		position = 0,
		section = ADVANCED_SECTION
	)
	default String markerData()
	{
		return "";
	}
}

package com.spawnmarker;

import com.google.common.base.Strings;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.*;

import javax.annotation.Nullable;
import javax.inject.Inject;
import java.awt.*;
import java.util.Collection;

public class SpawnMarkerOverlay extends Overlay {

    private static final int MAX_DRAW_DISTANCE = 32;

    private final Client client;
    private final SpawnMarkerPlugin plugin;

    @Inject
    private SpawnMarkerOverlay(Client client, SpawnMarkerPlugin plugin) {
        this.plugin = plugin;
        this.client = client;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
        setPriority(OverlayPriority.LOW);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        final Collection<ColorTileMarker> points = plugin.getPoints();
        for (final ColorTileMarker point : points) {
            if (plugin.isNpcNameHidden(point.getLabel())) {
                continue;
            }

            WorldPoint worldPoint = point.getWorldPoint();
            if (worldPoint.getPlane() != client.getPlane()) {
                continue;
            }

            Color tileColor = point.getColor();
            drawTile(graphics, worldPoint, tileColor, point.getLabel());
        }

        return null;
    }

    private void drawTile(Graphics2D graphics, WorldPoint point, Color color, @Nullable String label) {
        WorldPoint playerLocation = client.getLocalPlayer().getWorldLocation();

        if (point.distanceTo(playerLocation) >= MAX_DRAW_DISTANCE) {
            return;
        }

        LocalPoint lp = LocalPoint.fromWorld(client, point);
        if (lp == null) {
            return;
        }

        Polygon poly = Perspective.getCanvasTilePoly(client, lp);
        if (poly != null) {
            OverlayUtil.renderPolygon(graphics, poly, color);
        }

        if (!Strings.isNullOrEmpty(label)) {
            Point canvasTextLocation = Perspective.getCanvasTextLocation(client, graphics, lp, label, 0);
            if (canvasTextLocation != null) {
                OverlayUtil.renderTextLocation(graphics, canvasTextLocation, label, color);
            }
        }
    }

}

package com.spawnmarker;

import com.google.common.base.Strings;
import com.google.common.collect.ImmutableSet;
import com.google.gson.Gson;
import com.google.inject.Provides;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NpcID;
import net.runelite.api.Player;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.NpcSpawned;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import org.apache.commons.lang3.StringUtils;

import javax.inject.Inject;
import java.awt.*;
import java.nio.charset.StandardCharsets;
